function TeamContextCards({ selected, weights }) {
  const anyCtx = selected.some((p) => getLatestTeamContext(p));
  if (!anyCtx) return null;

  return (
    <div className="grid gap-3" style={{ gridTemplateColumns: `repeat(${selected.length}, minmax(0,1fr))` }}>
      {selected.map((p, i) => {
        const ctx = getLatestTeamContext(p);
        if (!ctx) {
          return (
            <Card key={p.id} className="text-xs text-slate-400">
              <CardContent className="pt-4">
                No team context available for {p.name} (no team data for a season they played).
              </CardContent>
            </Card>
          );
        }
        const lastStats = p.seasons[ctx.season];
        const rawFP = fp(lastStats, weights);
        const neutralFP = fp(teamNeutralStats(lastStats, ctx), weights);
        const delta = rawFP - neutralFP;
        let tag, tagColor;
        if (delta > 1.5) {
          tag = "Scoring context is inflating output";
          tagColor = "text-amber-700 bg-amber-50 border-amber-200";
        } else if (delta < -1.5) {
          tag = "Outproducing a weak team context";
          tagColor = "text-emerald-700 bg-emerald-50 border-emerald-200";
        } else {
          tag = "Roughly in line with team context";
          tagColor = "text-slate-500 bg-slate-50 border-slate-200";
        }

        return (
          <Card key={p.id}>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm flex items-center gap-2">
                <span className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: PLAYER_COLORS[i] }} />
                {ctx.team} team context — {SEASON_LABEL(ctx.season)}
                <HelpDot text="How good is this player's team? Used to tell whether their fantasy output is being helped or hurt by their surroundings." />
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 gap-2 mb-3">
                <div className="rounded bg-slate-50 px-2 py-1.5">
                  <div className="text-[10px] uppercase text-slate-400 font-semibold flex items-center gap-1">
                    Offense <HelpDot text="Team goals scored per game, ranked out of 32 NHL teams." />
                  </div>
                  <div className="font-bold text-sm text-[#0B1F33]">{ordinal(ctx.offenseRank)} · {ctx.gfPerGp} GF/GP</div>
                </div>
                <div className="rounded bg-slate-50 px-2 py-1.5">
                  <div className="text-[10px] uppercase text-slate-400 font-semibold flex items-center gap-1">
                    Defense <HelpDot text="Team goals allowed per game, ranked out of 32 (1st = stingiest)." />
                  </div>
                  <div className="font-bold text-sm text-[#0B1F33]">{ordinal(ctx.defenseRank)} · {ctx.gaPerGp} GA/GP</div>
                </div>
                <div className="rounded bg-slate-50 px-2 py-1.5">
                  <div className="text-[10px] uppercase text-slate-400 font-semibold flex items-center gap-1">
                    Power Play <HelpDot text="Team's power-play scoring rate, ranked out of 32." />
                  </div>
                  <div className="font-bold text-sm text-[#0B1F33]">{ordinal(ctx.ppRank)} in NHL</div>
                </div>
                <div className="rounded bg-slate-50 px-2 py-1.5">
                  <div className="text-[10px] uppercase text-slate-400 font-semibold flex items-center gap-1">
                    Penalty Kill <HelpDot text="Team's penalty-kill rate, ranked out of 32 (1st = best PK)." />
                  </div>
                  <div className="font-bold text-sm text-[#0B1F33]">{ordinal(ctx.pkRank)} in NHL</div>
                </div>
              </div>
              <div className={`rounded border px-2 py-1.5 text-xs font-semibold ${tagColor}`}>
                {tag}
                <span className="block font-normal text-[11px] mt-0.5 opacity-80">
                  {rawFP.toFixed(1)} FP actual vs {neutralFP.toFixed(1)} FP if this were a league-average
                  offense/PP context.
                </span>
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

function PlayerSearch({ onAdd, disabled, excludeIds }) {
  const [query, setQuery] = useState("");
  const results = useMemo(() => {
    if (!query.trim()) return [];
    const q = query.toLowerCase();
    return PLAYER_DATA.filter((p) => !excludeIds.includes(p.id) && playerNameMatchesSearch(p.name, q))
      .sort((a, b) => playerSearchRank(a, q) - playerSearchRank(b, q) || a.name.localeCompare(b.name))
      .slice(0, 8);
  }, [query, excludeIds]);

  return (
    <div className="relative">
      <div className="relative">
        <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
        <Input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          disabled={disabled}
          placeholder={disabled ? "Remove a player to add another (max 4)" : "Search a skater to chart..."}
          className="pl-9"
        />
      </div>
      {results.length > 0 && (
        <div className="absolute z-10 mt-1 w-full rounded-lg border border-slate-200 bg-white shadow-lg max-h-72 overflow-auto">
          {results.map((p) => (
            <button
              key={p.id}
              onClick={() => {
                onAdd(p);
                setQuery("");
              }}
              className="w-full text-left px-3 py-2 hover:bg-slate-50 flex items-center justify-between text-sm"
            >
              <span className="font-semibold text-[#0B1F33]">{p.name}</span>
              <span className="text-xs text-slate-400">{p.position} · {p.team}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/* ============================= RANKINGS TAB ============================= */
function RankingsTab({ weights }) {
  const [search, setSearch] = useState("");
  const [posFilter, setPosFilter] = useState("ALL");
  const [teamFilter, setTeamFilter] = useState("ALL");
  const [sortKey, setSortKey] = useState("latestFP");
  const [sortDir, setSortDir] = useState("desc");
  const [page, setPage] = useState(0);
  const [playerProfiles, setPlayerProfiles] = useState({});
  const pageSize = 24;

  const rows = useMemo(() => {
    return PLAYER_DATA.map((p) => {
      const ordered = getOrderedSeasons(p);
      const latestSeason = ordered[0];
      const latestFP = latestSeason ? fp(p.seasons[latestSeason], weights) : 0;
      const proj = projectPlayer(p, weights);
      const delta = trendArrow(p, weights);
      return {
        id: p.id,
        name: p.name,
        position: p.position,
        team: p.team,
        latestSeason,
        latestFP,
        projFP: proj ? proj.fp : 0,
        delta,
        player: p,
      };
    });
  }, [weights]);

  const filtered = useMemo(() => {
    let r = rows.filter((row) => {
      if (posFilter !== "ALL" && row.position !== posFilter) return false;
      if (teamFilter !== "ALL" && row.team !== teamFilter) return false;
      if (search.trim() && !playerNameMatchesSearch(row.name, search)) return false;
      return true;
    });
    r.sort((a, b) => {
      const dir = sortDir === "desc" ? -1 : 1;
      return (a[sortKey] - b[sortKey]) * dir;
    });
    return r;
  }, [rows, posFilter, teamFilter, search, sortKey, sortDir]);

  const paged = filtered.slice(page * pageSize, page * pageSize + pageSize);
  const maxPage = Math.max(0, Math.ceil(filtered.length / pageSize) - 1);

  useEffect(() => {
    const missing = paged.filter((row) => !playerProfiles[row.id]);
    if (!missing.length) return;

    let cancelled = false;
    Promise.all(
      missing.map((row) =>
        fetch(`https://api-web.nhle.com/v1/player/${row.id}/landing`)
          .then((response) => (response.ok ? response.json() : null))
          .then((data) => [row.id, data])
          .catch(() => [row.id, null])
      )
    ).then((entries) => {
      if (cancelled) return;
      setPlayerProfiles((current) => {
        const next = { ...current };
        entries.forEach(([id, data]) => {
          next[id] = {
            age: calculateAge(data?.birthDate),
            team: data?.currentTeamAbbrev || rows.find((row) => row.id === id)?.team,
            position: data?.position || rows.find((row) => row.id === id)?.position,
          };
        });
        return next;
      });
    });

    return () => {
      cancelled = true;
    };
  }, [paged, playerProfiles, rows]);

  const headerBtn = (key, label, helpText) => (
    <button
      onClick={() => {
        if (sortKey === key) setSortDir(sortDir === "desc" ? "asc" : "desc");
        else {
          setSortKey(key);
          setSortDir("desc");
        }
      }}
      className={`flex items-center gap-1 text-[11px] font-bold uppercase tracking-wide ${
        sortKey === key ? "text-[#1D6FA5]" : "text-slate-400"
      }`}
    >
      {label}
      <ArrowUpDown className="w-3 h-3" />
      {helpText && (
        <span onClick={(e) => e.stopPropagation()}>
          <HelpDot text={helpText} />
        </span>
      )}
    </button>
  );

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2 items-center">
        <div className="relative flex-1 min-w-[180px]">
          <Search className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" />
          <Input
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setPage(0);
            }}
            placeholder="Search skaters..."
            className="pl-9"
          />
        </div>
        <Select
          value={posFilter}
          onValueChange={(v) => {
            setPosFilter(v);
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[150px]">
            <SelectValue placeholder="Position" />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              <SelectItem value="ALL">All positions</SelectItem>
              {POSITIONS.map((pos) => (
                <SelectItem key={pos} value={pos}>{pos}</SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>
        <Select
          value={teamFilter}
          onValueChange={(v) => {
            setTeamFilter(v);
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[150px]">
            <SelectValue placeholder="Team" />
          </SelectTrigger>
          <SelectContent>
            <SelectGroup>
              <SelectItem value="ALL">All teams</SelectItem>
              {TEAMS.map((t) => (
                <SelectItem key={t} value={t}>{t}</SelectItem>
              ))}
            </SelectGroup>
          </SelectContent>
        </Select>
        <span className="text-xs text-slate-400 ml-auto">{filtered.length} skaters</span>
      </div>

      <div className="flex items-center justify-between rounded-xl border border-slate-200 bg-white px-4 py-3 shadow-sm">
        <div>
          <p className="text-[11px] font-bold uppercase tracking-wide text-slate-400">Sort player cards</p>
          <div className="mt-1 flex flex-wrap gap-3">
            {headerBtn("latestFP", "Last FP", "Fantasy points from their most recent season played.")}
            {headerBtn("delta", "YoY", "Year-over-year change in fantasy points vs the prior season.")}
            {headerBtn("projFP", "Proj FP", "Projected fantasy points for 2026-27.")}
          </div>
        </div>
        <div className="hidden sm:flex items-center gap-2 text-xs text-slate-400">
          <Shield className="w-4 h-4" />
          Photos and logos load from official NHL image assets.
        </div>
      </div>

      {paged.length === 0 ? (
        <Card>
          <CardContent className="px-4 py-10 text-center text-sm text-slate-400">
            No skaters match those filters. Try clearing the search or position/team filters.
          </CardContent>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {paged.map((row, idx) => {
            const profile = playerProfiles[row.id] || {};
            const team = profile.team || row.team;
            const position = profile.position || row.position;
            return (
              <Card
                key={row.id}
                className="overflow-hidden border-slate-200 bg-white shadow-sm transition hover:-translate-y-0.5 hover:shadow-lg"
              >
                <div className="relative min-h-[160px] bg-gradient-to-br from-[#0B1F33] via-[#123451] to-[#1D6FA5] px-4 pt-4 text-white">
                  <div className="absolute right-3 top-3 rounded-full bg-white/90 p-2 shadow-sm">
                    <img
                      src={getTeamLogoUrl(team)}
                      alt={`${team} logo`}
                      className="h-10 w-10 object-contain"
                      loading="lazy"
                    />
                  </div>
                  <div className="flex items-start gap-4 pr-14">
                    <div className="relative h-28 w-28 shrink-0 overflow-hidden rounded-2xl border border-white/25 bg-white/10 shadow-inner">
                      <img
                        src={getPlayerPhotoUrl({ ...row.player, team })}
                        alt={`${row.name} headshot`}
                        className="h-full w-full object-cover object-top"
                        loading="lazy"
                        onError={(event) => {
                          event.currentTarget.onerror = null;
                          event.currentTarget.src = `https://assets.nhle.com/mugs/nhl/20242025/${team}/${row.id}.png`;
                        }}
                      />
                    </div>
                    <div className="min-w-0 pt-1">
                      <div className="mb-2 flex items-center gap-2">
                        {page === 0 && idx < 3 && <Star className="w-4 h-4 text-[#E8A33D] fill-[#E8A33D]" />}
                        <Badge className="bg-white/15 text-white hover:bg-white/20">#{page * pageSize + idx + 1}</Badge>
                      </div>
                      <h3 className="text-2xl font-black leading-none tracking-tight">{row.name}</h3>
                      <p className="mt-2 text-sm font-semibold text-slate-200">{team}</p>
                    </div>
                  </div>
                </div>
                <CardContent className="space-y-4 p-4">
                  <div className="grid grid-cols-3 gap-2">
                    <div className="rounded-xl bg-slate-50 p-3">
                      <p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Position</p>
                      <p className="mt-1 text-sm font-black text-[#0B1F33]">{positionLabel(position)}</p>
                    </div>
                    <div className="rounded-xl bg-slate-50 p-3">
                      <p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Age</p>
                      <p className="mt-1 text-sm font-black text-[#0B1F33]">{profile.age ?? "—"}</p>
                    </div>
                    <div className="rounded-xl bg-slate-50 p-3">
                      <p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Team</p>
                      <p className="mt-1 text-sm font-black text-[#0B1F33]">{team}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-3 gap-2 border-t border-slate-100 pt-4 text-center">
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Last FP</p>
                      <p className="font-mono text-lg font-black tabular-nums text-[#0B1F33]">{row.latestFP.toFixed(1)}</p>
                    </div>
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">YoY</p>
                      <p className={`font-mono text-lg font-black tabular-nums ${row.delta >= 0 ? "text-emerald-600" : "text-rose-600"}`}>
                        {row.delta >= 0 ? "+" : ""}{row.delta.toFixed(1)}
                      </p>
                    </div>
                    <div>
                      <p className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Proj FP</p>
                      <p className="font-mono text-lg font-black tabular-nums text-[#1D6FA5]">{row.projFP.toFixed(1)}</p>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}

      <div className="flex items-center justify-between text-sm">
        <Button variant="outline" size="sm" disabled={page === 0} onClick={() => setPage(page - 1)}>
          Previous
        </Button>
        <span className="text-slate-400 text-xs">
          Page {page + 1} of {maxPage + 1}
        </span>
        <Button variant="outline" size="sm" disabled={page >= maxPage} onClick={() => setPage(page + 1)}>
          Next
        </Button>
      </div>
    </div>
  );
}

/* ============================= HOW-IT-WORKS POPOVER ============================= */
function HowItWorksPopover() {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm">
          <HelpCircle className="w-3.5 h-3.5 mr-1.5" />
          How this works
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-80 text-sm leading-relaxed" align="end">
        <p className="font-bold text-[#0B1F33] mb-1.5">Quick start</p>
        <p className="text-slate-600 mb-3">
          Search a player, see their fantasy points change season to season, and check a projection
          for next year. Hover the <HelpCircle className="w-3 h-3 inline -mt-0.5" /> icons anywhere
          for a plain-language explanation of what a stat or number means.
        </p>
        <p className="font-bold text-[#0B1F33] mb-1.5">How the projection works</p>
        <p className="text-slate-600">
          It blends a recency-weighted trend (last 3 seasons, weighted 50/30/20) with regression
          toward the player's career average, then nudges for team scoring context (offense, power
          play, defense), dampened 50% since team strength itself changes year to year. This
          dataset has no birthdates, so there's no true age curve — treat it as an estimate, not a
          guarantee.
        </p>
      </PopoverContent>
    </Popover>
  );
}

/* ============================= MAIN APP ============================= */
export default function App() {
  const [weights, setWeights] = useState(DEFAULT_WEIGHTS);
  const [weightsOpen, setWeightsOpen] = useState(false);
  const [tab, setTab] = useState("explore");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [selected, setSelected] = useState([]);

  const addPlayer = (p) => {
    if (selected.length >= 4) return;
    if (selected.find((s) => s.id === p.id)) return;
    setSelected([...selected, p]);
  };
  const removePlayer = (id) => setSelected(selected.filter((s) => s.id !== id));
  const tryExample = () => {
    const seed = ["Connor McDavid", "Cale Makar"];
    setSelected(PLAYER_DATA.filter((p) => seed.includes(p.name)).slice(0, 2));
  };

  return (
    <TooltipProvider delayDuration={150}>
      <div className="min-h-screen bg-[#EEF3F7] text-[#0B1F33]">
        <div className="max-w-6xl mx-auto px-4 py-6">
          <header className="mb-5">
            <div className="flex items-center justify-between flex-wrap gap-3">
              <div>
                <h1 className="text-2xl font-black tracking-tight uppercase">Puck Trends</h1>
                <p className="text-sm text-slate-500">
                  Active skater progression, 2020-21 through 2025-26, with 2026-27 projections
                </p>
              </div>
              <div className="flex items-center gap-2">
                <HowItWorksPopover />
                <Button
                  variant="outline"
                  size="icon"
                  className="md:hidden"
                  onClick={() => setSidebarOpen((open) => !open)}
                  aria-label="Open navigation"
                >
                  <Menu className="w-4 h-4" />
                </Button>
                <Tabs value={tab} onValueChange={setTab} className="hidden md:block">
                  <TabsList>
                    <TabsTrigger value="explore">Player Explorer</TabsTrigger>
                    <TabsTrigger value="rankings">Rankings</TabsTrigger>
                    <TabsTrigger value="trade">Trade Analyzer</TabsTrigger>
                  </TabsList>
                </Tabs>
              </div>
            </div>
            <div className="h-px mt-4 bg-gradient-to-r from-transparent via-[#E4572E]/50 to-transparent" />
          </header>

          {sidebarOpen && (
            <div className="fixed inset-0 z-50 md:hidden">
              <button
                type="button"
                className="absolute inset-0 bg-slate-950/50"
                onClick={() => setSidebarOpen(false)}
                aria-label="Close navigation"
              />
              <div className="relative h-full w-72 bg-white shadow-xl p-4 space-y-2">
                <div className="flex items-center justify-between pb-2">
                  <p className="text-sm font-bold uppercase tracking-tight">Navigation</p>
                  <Button variant="ghost" size="icon" onClick={() => setSidebarOpen(false)} aria-label="Close navigation">
                    <X className="w-4 h-4" />
                  </Button>
                </div>
                {[
                  ["explore", "Player Explorer"],
                  ["rankings", "Rankings"],
                  ["trade", "Trade Analyzer"],
                ].map(([value, label]) => (
                  <Button
                    key={value}
                    variant={tab === value ? "secondary" : "ghost"}
                    className="w-full justify-start"
                    onClick={() => {
                      setTab(value);
                      setSidebarOpen(false);
                    }}
                  >
                    {label}
                  </Button>
                ))}
              </div>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-[280px_1fr] gap-5">
            <aside className="space-y-4">
              <WeightsPanel weights={weights} setWeights={setWeights} open={weightsOpen} setOpen={setWeightsOpen} />
              {tab === "explore" && (
                <Card>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-sm uppercase tracking-tight">Compare Skaters</CardTitle>
                    <CardDescription>Up to 4 at once.</CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="flex flex-wrap gap-2 mb-2">
                      {selected.map((p, i) => (
                        <PlayerChip key={p.id} player={p} color={PLAYER_COLORS[i]} onRemove={() => removePlayer(p.id)} />
                      ))}
                    </div>
                    <PlayerSearch
                      onAdd={addPlayer}
                      disabled={selected.length >= 4}
                      excludeIds={selected.map((s) => s.id)}
                    />
                  </CardContent>
                </Card>
              )}
              <Alert>
                <Info className="w-4 h-4" />
                <AlertTitle className="text-xs uppercase tracking-wide">Roster note</AlertTitle>
                <AlertDescription className="text-xs">
                  Only skaters who played in 2025-26 are included — anyone missing from that season
                  is assumed to no longer be active.
                </AlertDescription>
              </Alert>
            </aside>

            <main className="space-y-4">
              {tab === "explore" ? (
                selected.length === 0 ? (
                  <EmptyExplorerState onTryExample={tryExample} />
                ) : (
                  <>
                    <ScoreboardHeader selected={selected} weights={weights} />
                    <TeamContextCards selected={selected} weights={weights} />
                    <FPTrendChart selected={selected} weights={weights} />
                    <ProjectionCards selected={selected} weights={weights} />
                    <StatSmallMultiples selected={selected} />
                  </>
                )
              ) : (
                <RankingsTab weights={weights} />
              )}
            </main>
          </div>
        </div>
      </div>
    </TooltipProvider>
  );
}
